tests:
assert repack_tensor_offsets([('a', 33), ('b', 16), ('c', 64)], 32) == {'a': 0, 'b': 64, 'c': 96}
assert repack_tensor_offsets([('x', 32), ('y', 0), ('z', 1)], 32) == {'x': 0, 'y': 32, 'z': 32}
assert repack_tensor_offsets([], 32) == {}
for bad_args in [([('a', 10)], 0), ([('a', 10)], -4), ([('a', -1)], 32), ([('a', 8), ('a', 8)], 32)]:
    raised = False
    try:
        repack_tensor_offsets(*bad_args)
    except ValueError:
        raised = True
    assert raised is True
